
import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';

// ⬇️ Adjust import path to your godigital-lib
import { StoreDbService, OBJECTNAME, UtilsService } from 'godigital-lib';

export interface ExploreTour {
  id: string;
  title: string;
  slug?: string;
  location: string;
  durationHours: number;
  maxPeople: number;
  priceFrom: number;
  coverImageUrl?: string;
  ownerName?: string;
  rating?: number;
  reviewsCount?: number;
  highlightOfMonth?: boolean;
}

@Component({
  selector: 'app-explore-tours',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './exploreTours.component.html'
})
export class ExploreToursComponent implements OnInit {

  loading = true;
  error?: string;
  tours: ExploreTour[] = [];

  constructor(
    private storeDb: StoreDbService,
    public utilSvc: UtilsService
  ) {}

  async ngOnInit() {
    try {
      // Example: get all events/tours, then filter locally on highlightOfMonth
      const data: any = await this.storeDb.getObject(
        OBJECTNAME.bnEvents, // 🔧 change to bnBoats / bnBoatServices / your own
        -1
      );

      if (!data) {
        this.tours = [];
      } else {
        // utils.objectToArray usually converts {id: obj, ...} -> [obj...]
        const rawArray = this.utilSvc.objectToArray(data) as any[];

        this.tours = rawArray
          .map(item => this.mapToExploreTour(item))
          .filter(t => t.highlightOfMonth); // keep only highlights
      }
    } catch (e) {
      console.error(e);
      this.error = 'Unable to load tours right now. Please try again later.';
    } finally {
      this.loading = false;
    }
  }

  /**
   * Map raw Firebase object to our ExploreTour interface
   * 🔧 Adapt field names here to match your backend schema.
   */
  private mapToExploreTour(item: any): ExploreTour {
    return {
      id: item.id || item.eventId || item.boatId || '',
      title: item.title || item.name || 'Boat tour',
      slug: item.slug || item.id || item.eventId,
      location: item.location || item.city || 'Unknown location',
      durationHours: item.durationHours || item.duration || 3,
      maxPeople: item.maxPeople || item.capacity || 8,
      priceFrom: item.priceFrom || item.price || 0,
      coverImageUrl: item.coverImageUrl || item.mainImage || item.photoUrl,
      ownerName: item.ownerName || item.owner?.name,
      rating: item.rating || item.averageRating,
      reviewsCount: item.reviewsCount || item.nbReviews,
      highlightOfMonth: item.highlightOfMonth === true || item.highlight === true
    };
  }

  /**
   * Navigate to the tour detail – you can route with slug or id.
   * Here we assume route: /tours/:id
   */
  trackById(_index: number, tour: ExploreTour) {
    return tour.id;
  }
}
