import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterLink } from '@angular/router';

import { UtilsService, StoreDbService, OBJECTNAME } from 'godigital-lib';

interface HeroBadge {
  label: string;
  icon?: string;
  style?: string;
}

interface MainpageDoc {
  mainpageId: string;
  ownerId: string;
  siteName: string;

  heroTitle?: string;
  heroLead?: string;
  heroImage?: string;
  heroBadges_json?: HeroBadge[];
}

interface EventCard {
  mainpageId: string;
  eventId: string;
  title: string;
  subtitle?: string;
  imageUrls: string[];
  durationLabel?: string;
  locationLabel?: string;
  footerLeft?: string;
  ctaLabel?: string;
  priceLabel?: string;
}

@Component({
  selector: 'app-tours-list',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './tours-list.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TourslistComponent implements OnInit {

  mainpageId!: string;
  boatId: string = '1000001';
  mainpage?: MainpageDoc;
  events: EventCard[] = [];

  loading = false;
  error?: string;

  // Same bucket / root as your mainpage component
  private readonly storageBucket = 'adn-dev-4d05d.appspot.com';
  private readonly storageRootFolder = 'mainpages';

  constructor(
    private route: ActivatedRoute,
    private storeDb: StoreDbService,
    private utilsSvc: UtilsService,
    private cdr: ChangeDetectorRef
  ) {}

  async ngOnInit(): Promise<void> {
    this.loading = true;
    this.error = undefined;
    this.cdr.markForCheck();

    try {
      // Boat ID (RTDB: backendowners/events/{boatId})
      this.boatId = this.route.snapshot.queryParamMap.get('boatId') || '1000001';

      // 1) Determine mainpageId from ?mainpage= or subdomain
      const rawFromQuery = this.route.snapshot.queryParamMap.get('mainpage');
      const raw =
        rawFromQuery ||
        this.detectMainpageFromSubdomain() ||
        'layali';

      const { id } = this.normalizeMainpageId(raw);
      this.mainpageId = id;

      // 2) Load mainpage + events in sequence
      await this.loadMainpage();
      await this.loadEvents();

    } catch (err: any) {
      console.error('[ToursListComponent] init error', err);
      this.error = 'Unable to load experiences for this boat owner.';
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  // ---------------------------------------------------------------------------
  // MAINPAGE ID RESOLUTION
  // ---------------------------------------------------------------------------

  private normalizeMainpageId(raw: string): { id: string; slug: string } {
    const trimmed = raw.trim();
    const lower = trimmed.toLowerCase();

    if (lower.startsWith('owner-home-')) {
      const slug = lower.substring('owner-home-'.length);
      return { id: lower, slug };
    }
    return {
      id: `owner-home-${lower}`,
      slug: lower
    };
  }

  private detectMainpageFromSubdomain(): string | null {
    if (typeof window === 'undefined') return null;

    const host = window.location.hostname; // e.g. layali.boatify.com
    const parts = host.split('.');

    if (parts.length > 2) {
      const sub = parts[0];
      if (sub && sub !== 'www' && sub !== 'localhost') {
        return sub;
      }
    }
    return null;
  }

  // ---------------------------------------------------------------------------
  // DATA LOADERS
  // ---------------------------------------------------------------------------

  private async loadMainpage(): Promise<void> {
    // New RTDB structure: backendowners/mainpage (single document)
    const doc = await this.storeDb.getObject(
      'backendowners/mainpage',
      null as any
    ) as MainpageDoc | null;

    if (!doc) {
      this.error = 'Homepage configuration not found for this owner.';
      throw new Error('mainpage not found');
    }

    // Keep a stable identifier for routing / legacy URL patterns
    const stableId = (doc as any).ownerId || (doc as any).mainpageId || this.mainpageId;
    (doc as any).mainpageId = stableId;
    this.mainpageId = stableId;

    this.mainpage = doc;
  }

  /** Load events from /backendevents/<mainpageId> */
  private async loadEvents(): Promise<void> {
    // New RTDB structure: backendowners/events/{boatId}
    const node = await this.storeDb.getObject(
      'backendowners/events',
      this.boatId
    ) as any | null;

    if (!node) {
      this.events = [];
      return;
    }

    const rawArray = this.utilsSvc.objectToArray(node) as any[];

    this.events = rawArray
      .map(row => this.mapToEventCard(row))
      .filter(ev => !!ev.eventId);
  }

  /** Map a raw RTDB row into an EventCard */
  private mapToEventCard(row: any): EventCard {
    const eventId = row.eventId || row.id || row.slug || row.key || '';
    const title = row.title || 'Boat experience';
    const subtitle = row.subtitle || row.tagline || '';

    const mainImage = row.mainImage || row.coverImage || row.image || '';

    // images_json: ["events/sunset/1.jpg", "events/sunset/2.jpg", ...]
    const rawImages: string[] =
      (Array.isArray(row.images_json) && row.images_json.length
        ? row.images_json
        : (mainImage ? [mainImage] : [])) || [];

    const imageUrls = rawImages
      .map((rel: string) => this.buildStorageUrl(rel))
      .filter((u): u is string => !!u);

    const durationLabel =
      row.durationLabel ||
      row.duration ||
      (row.durationHours ? `${row.durationHours}h` : '');

    const locationLabel = row.locationLabel || row.location || row.area || '';

    const footerLeft =
      row.footerLeft ||
      row.footer ||
      (row.withSkipper ? 'With skipper' : '');

    const ctaLabel = row.ctaLabel || 'View experience';

    const priceLabel =
      typeof row.priceFrom === 'number'
        ? `From €${row.priceFrom}`
        : row.priceLabel || '';

    return {
      mainpageId: this.mainpageId,
      eventId,
      title,
      subtitle,
      imageUrls,
      durationLabel,
      locationLabel,
      footerLeft,
      ctaLabel,
      priceLabel
    };
  }

  // ---------------------------------------------------------------------------
  // STORAGE URL BUILDER
  // ---------------------------------------------------------------------------

  /**
   * Build public URL to Firebase Storage.
   *
   * Supports:
   *  1) "events/sunset/1.jpg"
   *  2) "owner-home-layali/events/sunset/1.jpg"
   *  3) "mainpages/owner-home-layali/events/sunset/1.jpg"
   *  4) "boatowners/{firebaseUid}/events/..." (new bucket structure)
   *  5) full URL "https://firebasestorage.googleapis.com/..."
   */
  private buildStorageUrl(relativePath?: string | null): string | undefined {
    if (!relativePath) return undefined;

    // Already a full URL → keep as is
    if (/^https?:\/\//i.test(relativePath)) {
      return relativePath;
    }

    let clean = relativePath.trim().replace(/^\/+/, '');

    // New bucket structure: already a full storage object path.
    if (clean.startsWith('boatowners/')) {
      const encodedPath = encodeURIComponent(clean);
      return `https://firebasestorage.googleapis.com/v0/b/${this.storageBucket}/o/${encodedPath}?alt=media`;
    }

    // Case 3: already "mainpages/..."
    if (clean.startsWith(`${this.storageRootFolder}/`)) {
      const encodedPath = encodeURIComponent(clean);
      return `https://firebasestorage.googleapis.com/v0/b/${this.storageBucket}/o/${encodedPath}?alt=media`;
    }

    // Case 2: "owner-home-xxx/..."
    if (this.mainpageId && clean.startsWith(`${this.mainpageId}/`)) {
      clean = `${this.storageRootFolder}/${clean}`;
      const encodedPath = encodeURIComponent(clean);
      return `https://firebasestorage.googleapis.com/v0/b/${this.storageBucket}/o/${encodedPath}?alt=media`;
    }

    // Case 1: only subfolder under this mainpage
    const storagePath = `${this.storageRootFolder}/${this.mainpageId}/${clean}`;
    const encodedPath = encodeURIComponent(storagePath);
    return `https://firebasestorage.googleapis.com/v0/b/${this.storageBucket}/o/${encodedPath}?alt=media`;
  }

  // ---------------------------------------------------------------------------
  // TEMPLATE HELPERS
  // ---------------------------------------------------------------------------

  get heroImageUrl(): string | undefined {
    if (!this.mainpage || !this.mainpage.heroImage) return undefined;
    return this.buildStorageUrl(this.mainpage.heroImage);
  }

  get siteTitle(): string {
    if (!this.mainpage) return 'Experiences';
    // Example: "Experiences by Layali"
    return this.mainpage.siteName
      ? `Experiences by ${this.mainpage.siteName}`
      : 'Experiences';
  }

  get heroLead(): string {
    if (!this.mainpage?.heroLead) {
      return 'Browse all signature experiences offered by this boat owner.';
    }
    return this.mainpage.heroLead;
  }

  heroBadgeClass(badge: HeroBadge): string {
    if (badge.style === 'dark') {
      return 'badge text-bg-dark badge-rounded';
    }
    return 'badge text-bg-light border badge-rounded';
  }

  heroBadgeIconClasses(badge: HeroBadge): any {
    return badge.icon ? ['bi', badge.icon, 'me-1'] : null;
  }

  eventMainImage(ev: EventCard): string | undefined {
    return ev.imageUrls && ev.imageUrls.length ? ev.imageUrls[0] : undefined;
  }

  eventLink(ev: EventCard): any[] {
    // You can change this to your real detail route
    // For example: ['/tours', this.mainpageId, ev.eventId]
    return ['/tours', ev.eventId];
  }
}
